head.script:
// dataType 분할 _2 : "" (default) / 미설정 / 데이터 유형 결정 규칙 축
//  - text / number / float / date / time / boolean 은 _1, bigDecimal / 통화 / 12 자리 반올림 / Footer, SubTotal 합계는 _3 에서 검증
scwin.tData = {
    "description" : "[column > P > dataType]<br/>Column 의 데이터 유형을 설정합니다.",
    "validation" : [
        "'' 설정 시, Column 의 데이터 유형을 설정하지 않습니다.",
        "미설정 시, Column 의 데이터 유형을 설정하지 않습니다.",
        "'' 설정 시, 바인딩된 DataList Column 의 dataType 속성값이 적용됩니다.",
        "Column 의 dataType 속성값을 설정하면 해당 속성이 우선 적용됩니다.",
        "dataType 속성을 설정하지 않고, inputType='calendar' 인 Column 은 config.xml 의 'WebSquare/gridView/column[@inputType='calendar']/dataType/@value' 설정값인 'date' 가 적용됩니다.",
        "dataType 속성을 설정하지 않고, inputType='calendar' 이 아닌 Column 은 DataList 컬럼의 dataType 이 적용됩니다.",
        "위 조건에 해당하지 않고 expression 속성이 설정되어 있으면 표현식으로 유형을 추정하여 SUM(), AVG(), MAX(), MIN(), rowStatus() 는 'number' 로, CALC(), DISPLAY(), DATALIST() 는 'text' 로 적용됩니다.",
    ]
}



scwin.gVar = {
    // 계산 원본 Column (q1, q2) 값
    "q1" : ["12345", "2000", "300", "45"],
    "q2" : ["10", "20", "30", "5"],
    // val Column 바인딩 값 (calendar 는 날짜값, 그 외는 문자열 순 / 숫자 크기 순 정렬이 달라지는 값)
    "val" : {
        "text" : ["10", "9", "100", "-5"],
        "calendar" : ["20261015", "20261001", "20261103", "20250228"]
    },
    // con_expression 값 -> expression 속성값
    "expression" : {
        "sum" : "SUM('q1','q2')",
        "avg" : "AVG('q1','q2')",
        "max" : "MAX('q1','q2')",
        "min" : "MIN('q1','q2')",
        "rowStatus" : "rowStatus()",
        "calc" : "CALC('q1+q2')",
        "display" : "DISPLAY('q1')",
        "datalist" : "DATALIST('q1')"
    }
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_dataType.setSelectedIndex(0);
    con_inputType.setValue("text");
    con_dltDataType.setValue("number");
    con_expression.setValue("sum");
    scwin.con_inputType_onviewchange();

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// expression 은 inputType=expression 일 때만 활성화
scwin.con_inputType_onviewchange = function () {
    con_expression.setDisabled(con_inputType.getValue() !== "expression");
}



// 현재 조건
scwin.getCondition = function () {
    let inputType = con_inputType.getValue();
    return {
        "dataType" : con_dataType.getValue(),
        "inputType" : inputType,
        "dltDataType" : con_dltDataType.getValue(),
        "expression" : (inputType === "expression") ? scwin.gVar.expression[con_expression.getValue()] : ""
    };
}



// comp 생성
//  - q1, q2 : 계산 원본 Column (DataList dataType=number 고정, 정렬 제외)
//  - val    : 검증 대상 Column (dataType / inputType / expression 을 옵션값으로 설정, 바인딩 DataList Column dataType 도 옵션값)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] q1, q2 는 DataList dataType=number 고정, val 이 inputType=expression 이면 displayFormat=#,##0 고정\n[절차] 조건 선택 -> Target 재생성 -> 셀 표시값 확인 / val 헤더 클릭(정렬) 후 셀 표시값 확인\n[확인] getColumnOption 반환값, 정렬 후 Row 순서와 셀 표시값 (expression 은 number 이면 천 단위 구분 표시, text 이면 문자 마스크 표시)\n[참고] CALC 는 bigDecimal 모듈 미설정 환경이면 계산값이 NaN 으로 표시"', '', 'label1');

    let cond = scwin.getCondition();
    let arrVal = scwin.gVar.val[cond.inputType === "calendar" ? "calendar" : "text"];

    // dataList 생성 (val Column 은 옵션에 따라 dataType 지정 / 미지정 / Column 자체 없음)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="q1" name="q1" dataType="number"></w2:column>';
    strDlt += '<w2:column id="q2" name="q2" dataType="number"></w2:column>';
    if (cond.dltDataType !== "__none") {
        strDlt += '<w2:column id="val" name="val"' + (cond.dltDataType !== '' ? ' dataType="' + cond.dltDataType + '"' : '') + '></w2:column>';
    }
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    let arrJSON = [];
    for (let i = 0; i < arrVal.length; i++) {
        let row = { "q1" : scwin.gVar.q1[i], "q2" : scwin.gVar.q2[i] };
        if (cond.dltDataType !== "__none") {
            row["val"] = arrVal[i];
        }
        arrJSON.push(row);
    }
    dlt_bind.setJSON(arrJSON, false);

    // val Column 속성 (미설정이면 속성 자체를 넣지 않고, "" 설정이면 dataType="" 를 그대로 넣는다)
    let attrVal = ' inputType="' + cond.inputType + '"';
    if (cond.dataType === "__empty") {
        attrVal += ' dataType=""';
    } else if (cond.dataType !== '') {
        attrVal += ' dataType="' + cond.dataType + '"';
    }
    if (cond.inputType === "expression") {
        attrVal += ' expression="' + cond.expression + '" displayFormat="#,##0"';
    }

    // target 생성 (헤더 클릭 정렬, q1 / q2 는 정렬 제외)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" sortable="true" sortEvent="onclick" id="" style="width:500px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="q1" sortable="false"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="q2" sortable="false"></w2:column>';
    strTarget += '<w2:column width="240" style="" inputType="text" id="column3" value="val"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="q1" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="q2" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="240" style="" id="val"' + attrVal + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 설정 조건 -> 적용된 데이터 유형, Row 별 셀 표시값 출력 (화면에 보이는 Row 순서)
//  - validation 1 ~ 3, 6 : dataType 미설정 / "" 설정 시 DataList Column dataType 을 따름 (DataList Column dataType 옵션 변경으로 비교)
//  - validation 4 : dataType 설정 시 DataList Column dataType 보다 우선
//  - validation 5 : inputType=calendar + dataType 미설정 시 date (날짜 포맷 표시)
//  - validation 7 : DataList 에 val Column 이 없을 때 expression 함수별 표시값 (number : 천 단위 구분 / text : 문자 마스크)
scwin.btn_checkCell_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let cond = scwin.getCondition();
    let isExpression = (cond.inputType === "expression");

    let dataTypeText = (cond.dataType === "__empty") ? "''" : (cond.dataType === '' ? "(미설정)" : cond.dataType);
    let dltText = (cond.dltDataType === "__none") ? "(Column 없음)" : (cond.dltDataType === '' ? "(미설정)" : cond.dltDataType);
    bottom.setReturnValue("dataType : " + dataTypeText
        + " / inputType : " + cond.inputType
        + (isExpression ? " / expression : " + cond.expression : "")
        + " / DataList Column dataType : " + dltText
        + " -> getColumnOption('val', 'dataType') : " + target1.getColumnOption("val", "dataType"));

    for (let i = 0; i < target1.getDataLength(); i++) {
        if (isExpression) {
            bottom.setReturnValue("Row " + i + " q1 : " + target1.getCellData(i, "q1") + " / q2 : " + target1.getCellData(i, "q2")
                + " -> val 셀 표시값 : " + target1.getCellDisplayData(i, "val"));
        } else {
            bottom.setReturnValue("Row " + i + " val 저장값 : " + target1.getCellData(i, "val")
                + " -> 셀 표시값 : " + target1.getCellDisplayData(i, "val"));
        }
    }
}
